effect.shader:
void main(){
    vec2 px = 1.0/acScreenSize;
    vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 c = src.a>0.0? src.rgb/src.a : src.rgb;
    float b = max(bands,2.0);
    vec3 q = floor(c*b)/(b-1.0);
    float l0 = dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(px.x,0.0)).rgb, vec3(0.333));
    float l1 = dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(px.x,0.0)).rgb, vec3(0.333));
    float l2 = dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(0.0,px.y)).rgb, vec3(0.333));
    float l3 = dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(0.0,px.y)).rgb, vec3(0.333));
    float g = abs(l0-l1) + abs(l2-l3);
    float outline = 1.0 - clamp(g*6.0*edge, 0.0, 1.0);
    gl_FragColor = vec4(clamp(q*outline,0.0,1.0),1.0)*src.a;
}
